using System.Globalization; using System.Windows; using System.Windows.Controls; using WPF_SEMANA02.Data; using WPF_SEMANA02.Models;
namespace WPF_SEMANA02.Views;
public partial class SalidasWindow : Window { public SalidasWindow(){InitializeComponent();Limpiar();} private string? Seleccion(ComboBox c)=>(c.SelectedItem as ComboBoxItem)?.Content?.ToString(); private void Guardar_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(Seleccion(cmbTipoDocumento))||string.IsNullOrWhiteSpace(txtNumeroDocumento.Text)||string.IsNullOrWhiteSpace(Seleccion(cmbTipoAuto))||string.IsNullOrWhiteSpace(txtTransportista.Text)||dpFecha.SelectedDate is null||!TimeSpan.TryParse(txtHora.Text,out var hora)||!double.TryParse(txtPeso.Text,NumberStyles.Any,CultureInfo.CurrentCulture,out var peso)||!double.TryParse(txtPesoIngreso.Text,NumberStyles.Any,CultureInfo.CurrentCulture,out var ingreso)||!double.TryParse(txtPesoSalida.Text,NumberStyles.Any,CultureInfo.CurrentCulture,out var salida)){MessageBox.Show("Se deben completar los campos con valores numéricos válidos.","Validación",MessageBoxButton.OK,MessageBoxImage.Warning);return;}AppData.Salidas.Add(new Salida{TipoDocumento=Seleccion(cmbTipoDocumento)!,NumeroDocumento=txtNumeroDocumento.Text.Trim(),Peso=peso,TipoAuto=Seleccion(cmbTipoAuto)!,NombreTransportista=txtTransportista.Text.Trim(),FechaYHora=dpFecha.SelectedDate.Value.Date+hora,PesoIngreso=ingreso,PesoSalida=salida});MessageBox.Show("Salida registrada correctamente.","Información",MessageBoxButton.OK,MessageBoxImage.Information);Limpiar();} private void Limpiar_Click(object s,RoutedEventArgs e)=>Limpiar(); private void Limpiar(){cmbTipoDocumento.SelectedIndex=-1;txtNumeroDocumento.Clear();txtPeso.Clear();cmbTipoAuto.SelectedIndex=-1;txtTransportista.Clear();dpFecha.SelectedDate=DateTime.Today;txtHora.Text=DateTime.Now.ToString("HH:mm");txtPesoIngreso.Clear();txtPesoSalida.Clear();} private void Volver_Click(object s,RoutedEventArgs e)=>Close(); }
